1	import { createServerClient } from "@supabase/ssr";
2	import { type NextRequest, NextResponse } from "next/server";
3	
4	export async function updateSession(request: NextRequest) {
5	  let supabaseResponse = NextResponse.next({ request });
6	
7	  const supabase = createServerClient(
8	    process.env.NEXT_PUBLIC_SUPABASE_URL!,
9	    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
10	    {
11	      cookies: {
12	        getAll() {
13	          return request.cookies.getAll();
14	        },
15	        setAll(cookiesToSet) {
16	          cookiesToSet.forEach(({ name, value }) =>
17	            request.cookies.set(name, value),
18	          );
19	          supabaseResponse = NextResponse.next({ request });
20	          cookiesToSet.forEach(({ name, value, options }) =>
21	            supabaseResponse.cookies.set(name, value, options),
22	          );
23	        },
24	      },
25	    },
26	  );
27	
28	  // Required: refreshes the auth token and keeps cookies in sync.
29	  // Do not add logic between createServerClient and this call.
30	  const {
31	    data: { user },
32	  } = await supabase.auth.getUser();
33	
34	  const authPages = ["/login", "/signup", "/forgot-password"];
35	  const isAuthPage = authPages.some((path) =>
36	    request.nextUrl.pathname.startsWith(path),
37	  );
38	  // /order/* adalah halaman self-order pelanggan (scan QR) — tanpa login.
39	  // /auth/callback menukar kode dari link email jadi sesi, sebelum user ada.
40	  // "/" adalah landing page publik untuk calon pengguna yang belum daftar.
41	  // /terms dan /privacy juga harus bisa dibaca tanpa login.
42	  const isPublicPath =
43	    isAuthPage ||
44	    request.nextUrl.pathname === "/" ||
45	    request.nextUrl.pathname.startsWith("/order") ||
46	    request.nextUrl.pathname.startsWith("/auth/callback") ||
47	    request.nextUrl.pathname.startsWith("/terms") ||
48	    request.nextUrl.pathname.startsWith("/privacy");
49	
50	  if (!user && !isPublicPath) {
51	    const url = request.nextUrl.clone();
52	    url.pathname = "/login";
53	    return NextResponse.redirect(url);
54	  }
55	
56	  if (user && isAuthPage) {
57	    const url = request.nextUrl.clone();
58	    url.pathname = "/dashboard";
59	    return NextResponse.redirect(url);
60	  }
61	
62	  return supabaseResponse;
63	}
