6	export type TransferState = { error: string | null };
7	
8	export async function addTransfer(
9	  businessId: string,
10	  _prevState: TransferState,
11	  formData: FormData,
12	): Promise<TransferState> {
13	  const date = formData.get("date") as string;
14	  const fromCode = formData.get("fromCode") as string;
15	  const toCode = formData.get("toCode") as string;
16	  const description = (formData.get("description") as string)?.trim();
17	  const amountRaw = formData.get("amount") as string;
18	
19	  if (!date) {
20	    return { error: "Tanggal wajib diisi." };
21	  }
22	  if (!fromCode || !toCode) {
23	    return { error: "Pilih akun asal dan tujuan." };
24	  }
25	  if (fromCode === toCode) {
26	    return { error: "Akun asal dan tujuan tidak boleh sama." };
27	  }
28	
29	  const amount = Number(amountRaw);
30	  if (!amountRaw || Number.isNaN(amount) || amount <= 0) {
31	    return { error: "Nominal harus angka lebih dari 0." };
32	  }
33	
34	  const supabase = await createClient();
35	
36	  const { error } = await supabase.rpc("post_journal_entry", {
37	    p_business_id: businessId,
38	    p_date: date,
39	    p_description: description ? `Transfer: ${description}` : "Transfer antar akun kas/bank",
40	    p_lines: [
41	      { account_code: toCode, debit: amount, credit: 0 },
42	      { account_code: fromCode, debit: 0, credit: amount },
43	    ],
44	  });
45	
46	  if (error) {
47	    return { error: error.message };
48	  }
49	
50	  revalidatePath(`/business/${businessId}/accounting/transfer-kas`);
51	  return { error: null };
52	}
