33	export async function GET(
34	  request: Request,
35	  { params }: { params: Promise<{ businessId: string }> },
36	) {
37	  const { businessId } = await params;
38	  const url = new URL(request.url);
39	  const type = url.searchParams.get("type") === "transactions" ? "transactions" : "menu";
40	  const period = parsePeriod(url.searchParams.get("period") ?? undefined);
41	  const { fromIso, toIsoExclusive } = getPeriodRange(
42	    period,
43	    url.searchParams.get("from") ?? undefined,
44	    url.searchParams.get("to") ?? undefined,
45	  );
46	
47	  const supabase = await createClient();
48	
49	  const { data: business } = await supabase
50	    .from("businesses")
51	    .select("id, tax_enabled, tax_rate, service_enabled, service_rate")
52	    .eq("id", businessId)
53	    .single();
54	
55	  if (!business) {
56	    return new Response("Not found", { status: 404 });
57	  }
58	
59	  let txQuery = supabase
60	    .from("transactions")
61	    .select(
62	      "invoice_number, date, subtotal, service, tax, total, total_item_disc, order_disc_amt, is_split, transaction_items(name, category, price, cost, qty)",
63	    )
64	    .eq("business_id", businessId)
65	    .eq("voided", false)
66	    .order("date", { ascending: true });
67	  if (fromIso) txQuery = txQuery.gte("date", fromIso);
68	  if (toIsoExclusive) txQuery = txQuery.lt("date", toIsoExclusive);
69	  const { data: transactions } = await txQuery;
70	  const txList = transactions ?? [];
71	
72	  let rows: (string | number)[][];
73	  let filename: string;
74	  const periodLabel =
75	    period === "today" ? fmtDate(new Date().toISOString()).replace(/\//g, "-") : period;
76	
77	  if (type === "menu") {
78	    rows = [
79	      ["Tanggal", "Name", "Sub Cat.", "Qty.", "Menu", "Modifier", "Sales", "Item", "Bill", "Net", "Modal", "Laba Kotor"],
80	    ];
81	    for (const tx of txList) {
82	      const dateStr = fmtDate(tx.date);
83	      for (const item of tx.transaction_items) {
84	        const qty = Number(item.qty);
85	        const sales = Number(item.price) * qty;
86	        const cost = Number(item.cost) * qty;
87	        rows.push([
88	          dateStr,
89	          item.name,
90	          item.category ?? "",
91	          qty,
92	          Number(item.price),
93	          0, // Modifier
94	          sales,
95	          0, // Item charge
96	          0, // Bill charge
97	          sales, // Net
98	          cost, // Modal
99	          sales - cost, // Laba Kotor
100	        ]);
101	      }
102	    }
103	    filename = `PenjMenu_${periodLabel}.csv`;
104	  } else {
105	    rows = [
106	      ["No. Invoice", "Tanggal", "Time", "Sub Total", "Disc. Menu", "Disc.%", "Discount", "Serv.%", "Serv.", "Tax %", "Tax", "Tot. Menu", "Tot. Item", "Tot. Bill", "Extra Charge", "Pbltn", "Grand Tot.", "Join Tab"],
107	    ];
108	    for (const tx of txList) {
109	      const pbltn = tx.transaction_items.reduce((s, i) => s + Number(i.qty), 0);
110	      rows.push([
111	        tx.invoice_number,
112	        fmtDate(tx.date),
113	        fmtTime(tx.date),
114	        Number(tx.subtotal),
115	        Number(tx.total_item_disc),
116	        0, // Disc.%
117	        Number(tx.order_disc_amt),
118	        business.service_enabled ? Number(business.service_rate) : 0,
119	        Number(tx.service),
120	        business.tax_enabled ? Number(business.tax_rate) : 0,
121	        Number(tx.tax),
122	        Number(tx.subtotal), // Tot. Menu
123	        0, // Tot. Item
124	        Number(tx.service) + Number(tx.tax), // Tot. Bill
125	        0, // Extra Charge
126	        pbltn,
127	        Number(tx.total), // Grand Tot.
128	        tx.is_split ? "Ya" : "Tidak",
129	      ]);
130	    }
131	    filename = `PenjTransaksi_${periodLabel}.csv`;
132	  }
133	
134	  // BOM (U+FEFF) supaya Excel membuka file sebagai UTF-8.
135	  return new Response(String.fromCharCode(0xfeff) + toCsv(rows), {
136	    headers: {
137	      "Content-Type": "text/csv; charset=utf-8",
138	      "Content-Disposition": `attachment; filename="${filename}"`,
139	    },
140	  });
141	}
